DO $$ BEGIN
 IF (SELECT count(*) FROM pg_tables WHERE schemaname='public')<>40 THEN RAISE EXCEPTION 'Postcheck 014: esperado 40 tabelas'; END IF;
 IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='fechamento_revisoes')<>68 OR (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='fechamento_revisao_adicionais')<>12 THEN RAISE EXCEPTION 'Postcheck 014: colunas divergentes'; END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger WHERE tgname IN ('fr_validar_trg','fra_validar_trg','fr_edicao_validar_trg','fr_fluxo_validar_trg','fr_versao_validar_trg','fr_assinatura_validar_trg','fr_aprovacao_validar_trg','fr_fechamento_proteger_trg','fr_adicionais_proteger_trg','fr_base_proteger_trg','fr_agenda_validar_trg') AND NOT tgdeferrable) THEN RAISE EXCEPTION 'Postcheck 014: trigger não diferido'; END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgname IN ('fr_preservar_trg','fr_atualizado_trg','fra_preservar_trg','fra_atualizado_trg','fr_validar_trg','fra_validar_trg','fr_edicao_validar_trg','fr_fluxo_validar_trg','fr_versao_validar_trg','fr_assinatura_validar_trg','fr_aprovacao_validar_trg','fr_fechamento_proteger_trg','fr_adicionais_proteger_trg','fr_base_proteger_trg','fr_agenda_validar_trg','fr_confirmacao_agenda_trg','fr_bloqueio_proteger_trg','fr_aprovacao_preservar_trg'))<>18 THEN RAISE EXCEPTION 'Postcheck 014: triggers ausentes'; END IF;
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='contrato_assinaturas'::regclass AND confrelid='sessoes_administrativas'::regclass) THEN RAISE EXCEPTION 'Postcheck 014: FK sessão proibida'; END IF;
END $$;
